  <meta property="twitter:description" content="Save hours of UI & UX research with ScreenVault — a library of 400,000+ fully searchable mobile & web app screenshots, flows, and UI elements. Join free today.">
  <meta property="twitter:image" content="https://screenvault.com/og-image.png">
  <meta property="twitter:site" content="@screenvault">

  <!-- Favicon -->
  <link rel="icon" type="image/svg+xml" href="favicon.svg">

  <!-- JSON-LD Structured Data -->
  <script type="application/ld+json">
