        "reviewBody": "ScreenVault is a game-changer for designers looking to step up their understanding of UX and UI design patterns.",
        "reviewRating": { "@type": "Rating", "ratingValue": "5" }
      }
    ],
    "foundingDate": "2018",
    "sameAs": [
      "https://twitter.com/screenvault",
      "https://linkedin.com/company/screenvault"
    ]
  }
  </script>

  <style>
    /* ─── Reset & Base ─── */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    html { scroll-behavior: smooth; }
    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      background: #ffffff;
      color: #141414;
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
      overflow-x: hidden;
    }

    /* ─── Typography Scale ─── */
    h1 { font-size: clamp(2.4rem, 5vw, 4rem); font-weight: 700; letter-spacing: -0.03em; line-height: 1.12; }
    h2 { font-size: clamp(1.75rem, 3vw, 2.5rem); font-weight: 700; letter-spacing: -0.025em; line-height: 1.2; }
    h3 { font-size: 1.25rem; font-weight: 600; letter-spacing: -0.015em; }
    p  { color: #555; }

    /* ─── Utilities ─── */
    .container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
    .badge {
      display: inline-flex; align-items: center; gap: 6px;
      background: #f0f0f0; border: 1px solid #e0e0e0;
      border-radius: 999px; padding: 4px 12px;
      font-size: 0.78rem; font-weight: 500; color: #444; letter-spacing: 0.01em;
    }
    .badge .dot { width: 6px; height: 6px; background: #141414; border-radius: 50%; }

    /* ─── Buttons ─── */
    .btn {
      display: inline-flex; align-items: center; gap: 6px;
      padding: 11px 22px; border-radius: 10px;
      font-size: 0.9rem; font-weight: 600; text-decoration: none;
      cursor: pointer; border: none; transition: all 0.2s ease;
      white-space: nowrap;
    }
    .btn-primary {
      background: #141414; color: #fff;
    }
    .btn-primary:hover { background: #2d2d2d; transform: translateY(-1px); box-shadow: 0 4px 16px rgba(20,20,20,0.18); }
    .btn-ghost {
      background: transparent; color: #141414;
      border: 1.5px solid #ddd;
    }
    .btn-ghost:hover { border-color: #141414; background: #f9f9f9; }

    /* ─── Announcement Bar ─── */
    .announcement-bar {
      background: #141414; color: #fff;
      text-align: center; padding: 10px 16px;
      font-size: 0.82rem; font-weight: 500; letter-spacing: 0.01em;
    }
    .announcement-bar a { color: #fff; text-decoration: underline; text-underline-offset: 3px; }
    .announcement-bar a:hover { opacity: 0.8; }

    /* ─── Navigation ─── */
    .nav {
      position: sticky; top: 0; z-index: 100;
      background: rgba(255,255,255,0.92);
      backdrop-filter: blur(12px);
      border-bottom: 1px solid #f0f0f0;
    }
    .nav-inner {
      display: flex; align-items: center; justify-content: space-between;
      height: 60px; max-width: 1200px; margin: 0 auto; padding: 0 24px;
    }
    .nav-logo {
      font-size: 1.1rem; font-weight: 700; letter-spacing: -0.02em;
      color: #141414; text-decoration: none;
      display: flex; align-items: center; gap: 8px;
    }
    .nav-logo-icon {
      width: 28px; height: 28px; background: #141414; border-radius: 7px;
      display: flex; align-items: center; justify-content: center;
    }
    .nav-logo-icon svg { width: 16px; height: 16px; fill: #fff; }
    .nav-links {
      display: flex; align-items: center; gap: 28px; list-style: none;
    }
    .nav-links a {
      font-size: 0.875rem; font-weight: 500; color: #555;
      text-decoration: none; transition: color 0.15s;
    }
    .nav-links a:hover { color: #141414; }
    .nav-actions { display: flex; align-items: center; gap: 10px; }
    .nav-hamburger {
      display: none; flex-direction: column; gap: 5px;
      background: none; border: none; cursor: pointer; padding: 4px;
    }
    .nav-hamburger span {
      display: block; width: 22px; height: 2px;
      background: #141414; border-radius: 2px; transition: all 0.2s;
    }

    /* ─── Hero ─── */
    .hero {
      padding: 100px 24px 80px;
      text-align: center;
      background: radial-gradient(ellipse 80% 60% at 50% -10%, #f5f5f5 0%, transparent 70%);
    }
    .hero-badge { margin-bottom: 28px; }
    .hero h1 { max-width: 780px; margin: 0 auto 20px; }
    .hero h1 span { color: #141414; }
    .hero-sub {
      font-size: 1.05rem; max-width: 520px;
      margin: 0 auto 36px; color: #666;
    }
    .hero-actions {
      display: flex; align-items: center; justify-content: center;
      gap: 12px; flex-wrap: wrap; margin-bottom: 64px;
    }
    .hero-visual {
      max-width: 960px; margin: 0 auto;
      border-radius: 16px; overflow: hidden;
      box-shadow: 0 2px 8px rgba(0,0,0,0.06), 0 24px 80px rgba(0,0,0,0.1);
      border: 1px solid #e8e8e8;
    }
    .hero-visual-inner {
      background: #f5f5f5; padding: 32px 24px; min-height: 340px;
      display: grid; grid-template-columns: repeat(auto-fill, minmax(120px,1fr)); gap: 12px;
    }
    .hero-screen-card {
      background: #fff; border-radius: 12px; overflow: hidden;
      aspect-ratio: 9/16; border: 1px solid #ebebeb;
      box-shadow: 0 1px 4px rgba(0,0,0,0.06);
    }
    .hero-screen-card-inner {
      width: 100%; height: 100%;
      display: flex; flex-direction: column; gap: 8px; padding: 10px;
    }
    .screen-bar { height: 8px; background: #ebebeb; border-radius: 4px; }
    .screen-bar.short { width: 60%; }
    .screen-bar.medium { width: 80%; }
    .screen-circle {
      width: 32px; height: 32px; background: #e8e8e8; border-radius: 50%; margin-bottom: 4px;
    }
    .screen-rect { height: 40px; background: #f0f0f0; border-radius: 6px; }
    .screen-dots { display: flex; gap: 4px; }
    .screen-dots span {
      width: 6px; height: 6px; background: #ddd; border-radius: 50%;
    }

    /* ─── Trusted By ─── */
    .trusted-by {
      padding: 56px 24px;
      border-top: 1px solid #f0f0f0;
    }
    .trusted-by-label {
      text-align: center; font-size: 0.8rem; font-weight: 600;
      letter-spacing: 0.08em; text-transform: uppercase;
      color: #aaa; margin-bottom: 32px;
    }
    .trusted-logos {
      display: flex; align-items: center; justify-content: center;
      flex-wrap: wrap; gap: 32px 48px;
    }
    .logo-item {
      font-size: 0.95rem; font-weight: 700; color: #bbb;
      letter-spacing: -0.02em; transition: color 0.2s;
      white-space: nowrap;
    }
    .logo-item:hover { color: #888; }

    /* ─── Stats ─── */
    .stats {
      padding: 80px 24px;
      background: #141414; color: #fff;
      text-align: center;
    }
    .stats-intro {
      font-size: 0.85rem; font-weight: 600;
      letter-spacing: 0.1em; text-transform: uppercase;
      color: #666; margin-bottom: 12px;
    }
    .stats h2 { color: #fff; margin-bottom: 56px; }
    .stats-grid {
      display: grid; grid-template-columns: repeat(3, 1fr);
      gap: 40px; max-width: 700px; margin: 0 auto;
    }
    .stat-item {}
    .stat-number {
      font-size: clamp(2.5rem, 5vw, 3.8rem); font-weight: 800;
      letter-spacing: -0.04em; color: #fff;
      font-variant-numeric: tabular-nums;
    }
    .stat-label {
      font-size: 0.875rem; color: #888; margin-top: 4px; font-weight: 500;
    }

    /* ─── Section shared ─── */
    .section { padding: 96px 24px; }
    .section-header { text-align: center; margin-bottom: 56px; }
    .section-eyebrow {
      font-size: 0.8rem; font-weight: 600; letter-spacing: 0.1em;
      text-transform: uppercase; color: #999; margin-bottom: 12px;
    }
    .section-header h2 { margin-bottom: 12px; }
    .section-header p { font-size: 1.05rem; max-width: 520px; margin: 0 auto; }

    /* ─── Features: Search ─── */
    .features-search { background: #fafafa; }
    .search-ui {
      background: #fff; border: 1px solid #e8e8e8;
      border-radius: 16px; overflow: hidden;
      box-shadow: 0 2px 8px rgba(0,0,0,0.04), 0 16px 48px rgba(0,0,0,0.06);
      max-width: 900px; margin: 0 auto;
    }

    /* Tabs */
    .search-tabs {
      display: flex; border-bottom: 1px solid #f0f0f0;
      padding: 0 20px; gap: 0; background: #fafafa;
    }
    .search-tab {
      padding: 14px 18px; font-size: 0.875rem; font-weight: 500;
      color: #999; cursor: pointer; border: none; background: none;
      border-bottom: 2px solid transparent;
      transition: color 0.2s, border-color 0.2s;
      white-space: nowrap;
    }
    .search-tab:hover { color: #555; }
    .search-tab.active { color: #141414; border-bottom-color: #141414; }

    /* Filter pills */
    .filter-row {
      display: flex; gap: 8px; padding: 16px 20px;
      overflow-x: auto; scrollbar-width: none;
    }
    .filter-row::-webkit-scrollbar { display: none; }
    .filter-pill {
      flex-shrink: 0; padding: 6px 14px; border-radius: 999px;
      font-size: 0.82rem; font-weight: 500; cursor: pointer;
      border: 1.5px solid #e8e8e8; background: #fff; color: #555;
      transition: all 0.18s ease; white-space: nowrap;
    }
    .filter-pill:hover { border-color: #141414; color: #141414; }
    .filter-pill.active { background: #141414; color: #fff; border-color: #141414; }

    /* Grid */
    .screenshot-grid {
      display: grid; grid-template-columns: repeat(auto-fill, minmax(110px, 1fr));
      gap: 10px; padding: 16px 20px 20px;
      min-height: 240px;
    }
    .screenshot-card {
      background: #f5f5f5; border-radius: 10px; overflow: hidden;
      aspect-ratio: 9/16; border: 1px solid #ebebeb;
      transition: transform 0.2s, box-shadow 0.2s;
    }
    .screenshot-card:hover { transform: translateY(-2px); box-shadow: 0 4px 16px rgba(0,0,0,0.1); }
    .screenshot-card-inner {
      width: 100%; height: 100%; padding: 8px;
      display: flex; flex-direction: column; gap: 6px;
    }
    .sc-top { display: flex; align-items: center; gap: 5px; }
    .sc-avatar { width: 18px; height: 18px; background: #ddd; border-radius: 50%; flex-shrink: 0; }
    .sc-line { height: 6px; flex: 1; background: #e4e4e4; border-radius: 3px; }
    .sc-image { flex: 1; background: #e0e0e0; border-radius: 6px; }
    .sc-title { height: 6px; background: #ddd; border-radius: 3px; width: 80%; }
    .sc-subtitle { height: 6px; background: #ebebeb; border-radius: 3px; width: 55%; }
    .sc-button { height: 14px; background: #d0d0d0; border-radius: 4px; margin-top: 2px; }

    /* Tab content panels */
    .tab-panel { display: none; }
    .tab-panel.active { display: block; }

    /* UI Elements panel */
    .ui-elements-grid {
      display: grid; grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
      gap: 10px; padding: 16px 20px 20px; min-height: 240px;
    }
    .ui-element-card {
      background: #f8f8f8; border-radius: 10px; padding: 14px;
      border: 1px solid #ebebeb;
      transition: transform 0.2s, box-shadow 0.2s;
    }
    .ui-element-card:hover { transform: translateY(-2px); box-shadow: 0 4px 16px rgba(0,0,0,0.08); }
    .ue-label { font-size: 0.72rem; color: #aaa; margin-bottom: 8px; font-weight: 600; letter-spacing: 0.04em; text-transform: uppercase; }
    .ue-sample { height: 40px; background: #e4e4e4; border-radius: 6px; }
    .ue-nav { display: flex; gap: 4px; }
    .ue-nav span { flex: 1; height: 24px; background: #e0e0e0; border-radius: 4px; }
    .ue-card-row { display: flex; gap: 4px; }
    .ue-card-row span { flex: 1; height: 28px; background: #e0e0e0; border-radius: 5px; }
    .ue-input { height: 28px; background: #e8e8e8; border-radius: 5px; border: 1.5px solid #d0d0d0; }
    .ue-toggle { display: flex; align-items: center; gap: 6px; }
    .ue-toggle-track { width: 32px; height: 18px; background: #141414; border-radius: 9px; }
    .ue-toggle-label { font-size: 0.75rem; color: #888; }

    /* Flows panel */
    .flows-list { padding: 16px 20px 20px; min-height: 240px; display: flex; flex-direction: column; gap: 10px; }
    .flow-item {
      display: flex; align-items: center; gap: 12px;
      padding: 12px 14px; background: #f8f8f8; border-radius: 10px;
      border: 1px solid #ebebeb; cursor: pointer;
      transition: all 0.18s;
    }
    .flow-item:hover { background: #f0f0f0; border-color: #ddd; }
    .flow-thumb {
      width: 36px; height: 36px; background: #e0e0e0;
      border-radius: 8px; flex-shrink: 0;
    }
    .flow-info { flex: 1; }
    .flow-name { font-size: 0.875rem; font-weight: 600; color: #222; }
    .flow-meta { font-size: 0.75rem; color: #aaa; margin-top: 2px; }
    .flow-arrow { color: #ccc; font-size: 0.9rem; }
    .flow-count-badge {
      background: #f0f0f0; border-radius: 6px; padding: 2px 8px;
      font-size: 0.72rem; color: #888; font-weight: 600;
    }

    /* Text panel */
    .text-search-panel { padding: 16px 20px 20px; min-height: 240px; }
    .text-search-bar {
      display: flex; gap: 8px; margin-bottom: 16px;
    }
    .text-search-input {
      flex: 1; height: 38px; background: #f5f5f5; border: 1.5px solid #e8e8e8;
      border-radius: 8px; padding: 0 12px; font-size: 0.875rem;
      color: #141414; outline: none; font-family: inherit;
      transition: border-color 0.2s;
    }
    .text-search-input:focus { border-color: #141414; background: #fff; }
    .text-search-btn {
      height: 38px; padding: 0 16px; background: #141414; color: #fff;
      border-radius: 8px; border: none; font-size: 0.875rem; font-weight: 600;
      cursor: pointer; font-family: inherit; transition: background 0.2s;
    }
    .text-search-btn:hover { background: #333; }
    .text-results { display: grid; grid-template-columns: repeat(auto-fill, minmax(110px,1fr)); gap: 8px; }
    .text-result-card {
      background: #f8f8f8; border-radius: 8px; aspect-ratio: 9/16;
      border: 1px solid #ebebeb; position: relative; overflow: hidden;
    }
    .text-highlight {
      position: absolute; bottom: 30%; left: 10%; right: 10%;
      background: #fef3c7; border-radius: 3px; height: 8px;
    }

    /* ─── Features: Flows ─── */
    .features-flows { background: #fff; }
    .flows-toggle-wrapper { display: flex; justify-content: center; margin-bottom: 40px; }
    .flows-toggle {
      display: flex; background: #f5f5f5; border-radius: 10px; padding: 4px;
      gap: 2px;
    }
    .flows-toggle-btn {
      padding: 8px 20px; border-radius: 7px; font-size: 0.875rem; font-weight: 500;
      cursor: pointer; border: none; background: transparent; color: #888;
      transition: all 0.2s; font-family: inherit;
    }
    .flows-toggle-btn.active { background: #141414; color: #fff; }
    .flows-content-area {
      max-width: 860px; margin: 0 auto;
      background: #141414; border-radius: 16px; overflow: hidden;
      box-shadow: 0 24px 80px rgba(0,0,0,0.18);
      min-height: 380px;
    }
    .flows-panel { display: none; }
    .flows-panel.active { display: block; }

    /* Video view */
    .flows-video-view { padding: 32px; }
    .flows-video-header {
      display: flex; align-items: center; gap: 16px; margin-bottom: 24px;
    }
    .flows-app-icon {
      width: 48px; height: 48px; background: #2d2d2d; border-radius: 12px;
    }
    .flows-app-info h3 { color: #fff; font-size: 1rem; }
    .flows-app-info p { color: #888; font-size: 0.8rem; margin-top: 2px; }
    .flows-screens-row {
      display: flex; gap: 12px; overflow-x: auto; scrollbar-width: none; padding-bottom: 4px;
    }
    .flows-screens-row::-webkit-scrollbar { display: none; }
    .flows-screen-item {
      flex-shrink: 0; width: 80px;
      background: #222; border-radius: 10px; overflow: hidden;
      aspect-ratio: 9/16;
    }
    .flows-screen-item.active { box-shadow: 0 0 0 2px #fff; }
    .flows-screen-content { width: 100%; height: 100%; padding: 8px; display: flex; flex-direction: column; gap: 4px; }
    .fsc-bar { height: 5px; background: #3d3d3d; border-radius: 3px; }
    .fsc-bar.short { width: 55%; }
    .fsc-rect { flex: 1; background: #333; border-radius: 5px; }
    .fsc-btn { height: 12px; background: #4d4d4d; border-radius: 3px; }
    .flows-play-btn {
      display: flex; align-items: center; justify-content: center;
      gap: 8px; margin-top: 20px;
      background: #fff; color: #141414; border: none; border-radius: 10px;
      padding: 10px 20px; font-size: 0.875rem; font-weight: 600; cursor: pointer;
      font-family: inherit; transition: opacity 0.2s; width: 100%;
    }
    .flows-play-btn:hover { opacity: 0.9; }

    /* Prototype view */
    .flows-proto-view { padding: 32px; }
    .proto-steps { display: flex; flex-direction: column; gap: 0; }
    .proto-step {
      display: flex; gap: 16px; padding: 16px 0;
      border-bottom: 1px solid #222;
    }
    .proto-step:last-child { border-bottom: none; }
    .proto-step-num {
      width: 28px; height: 28px; background: #222; border-radius: 50%;
      display: flex; align-items: center; justify-content: center;
      font-size: 0.75rem; color: #888; font-weight: 600; flex-shrink: 0;
    }
    .proto-step-num.current { background: #fff; color: #141414; }
    .proto-step-info h4 { color: #fff; font-size: 0.875rem; margin-bottom: 2px; }
    .proto-step-info p { color: #888; font-size: 0.78rem; }
    .proto-step.current .proto-step-info h4 { color: #fff; }

    /* ─── Features: Tools ─── */
    .features-tools { background: #fafafa; }
    .tools-grid {
      display: grid; grid-template-columns: repeat(3, 1fr);
      gap: 20px; max-width: 900px; margin: 0 auto;
    }
    .tool-card {
      background: #fff; border-radius: 16px; padding: 32px 24px;
      border: 1px solid #ebebeb;
      transition: box-shadow 0.25s, transform 0.25s;
    }
    .tool-card:hover { box-shadow: 0 8px 32px rgba(0,0,0,0.08); transform: translateY(-3px); }
    .tool-icon {
      width: 44px; height: 44px; background: #141414; border-radius: 12px;
      display: flex; align-items: center; justify-content: center; margin-bottom: 18px;
    }
    .tool-icon svg { width: 22px; height: 22px; fill: none; stroke: #fff; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
    .tool-card h3 { font-size: 1rem; margin-bottom: 8px; color: #141414; }
    .tool-card p { font-size: 0.875rem; color: #777; line-height: 1.55; }

    /* ─── Testimonials ─── */
    .testimonials { padding: 96px 0; background: #fff; overflow: hidden; }
    .testimonials-header { text-align: center; margin-bottom: 48px; padding: 0 24px; }
