<script>
(function () {
  'use strict';

  /* ── Mobile nav ── */
  const menuToggle = document.getElementById('menuToggle');
  const mobileNav  = document.getElementById('mobileNav');
  menuToggle.addEventListener('click', function () {
    const open = mobileNav.classList.toggle('open');
    menuToggle.setAttribute('aria-expanded', open);
  });

  /* ── Generate hero screenshot grid ── */
  const heroGrid = document.getElementById('heroGrid');
  const colors = ['#f0edf8','#e8f4f0','#fdf2e8','#e8eef8','#f8e8ed','#edf8f2'];
  for (let i = 0; i < 14; i++) {
    const card = document.createElement('div');
    card.className = 'hero-screen-card';
    card.style.animationDelay = (i * 0.05) + 's';
    card.innerHTML = `<div class="hero-screen-card-inner" style="background:${colors[i % colors.length]}">
      <div class="screen-bar medium"></div>
      <div class="screen-circle"></div>
      <div class="screen-bar short"></div>
      <div class="screen-rect"></div>
      <div class="screen-dots"><span></span><span></span><span></span></div>
    </div>`;
    heroGrid.appendChild(card);
  }

  /* ── Stats counter animation ── */
  function formatNumber(n) {
    return n.toLocaleString('en-US');
  }

  function animateCounter(el, target, duration) {
    const start = performance.now();
    function update(now) {
      const elapsed = now - start;
      const progress = Math.min(elapsed / duration, 1);
      // ease-out cubic
      const eased = 1 - Math.pow(1 - progress, 3);
      el.textContent = formatNumber(Math.round(eased * target));
      if (progress < 1) requestAnimationFrame(update);
    }
    requestAnimationFrame(update);
  }

  let statsAnimated = false;
  const statsSection = document.getElementById('stats');
  const statEls = [
    { el: document.getElementById('stat-apps'),    target: 1150   },
    { el: document.getElementById('stat-screens'), target: 615900 },
    { el: document.getElementById('stat-flows'),   target: 329200 },
  ];

  const statsObserver = new IntersectionObserver(function (entries) {
    if (entries[0].isIntersecting && !statsAnimated) {
      statsAnimated = true;
      statEls.forEach(function (item, idx) {
        setTimeout(function () {
          animateCounter(item.el, item.target, 1800);
        }, idx * 180);
      });
    }
  }, { threshold: 0.3 });
  statsObserver.observe(statsSection);

  /* ── Search tabs ── */
  const tabs = document.querySelectorAll('.search-tab');
  const filterRow = document.getElementById('filterRow');

  tabs.forEach(function (tab) {
    tab.addEventListener('click', function () {
      tabs.forEach(function (t) {
        t.classList.remove('active');
        t.setAttribute('aria-selected', 'false');
      });
      tab.classList.add('active');
      tab.setAttribute('aria-selected', 'true');

      const tabName = tab.dataset.tab;
      document.querySelectorAll('.tab-panel').forEach(function (p) {
        p.classList.remove('active');
      });
      const panel = document.getElementById('panel-' + tabName);
      if (panel) panel.classList.add('active');

      // Show/hide filter row
      filterRow.style.display = (tabName === 'flows-tab' || tabName === 'text') ? 'none' : 'flex';
    });
  });

  /* ── Filter pills → screenshot grid ── */
  const screenshots = [
    { category: 'Profile',   label: 'Profile header' },
    { category: 'Wallet',    label: 'Balance card' },
    { category: 'Welcome',   label: 'Splash screen' },
    { category: 'Account Setup', label: 'Account setup' },
    { category: 'Home',      label: 'Home feed' },
    { category: 'Subscription & Paywall', label: 'Paywall screen' },
    { category: 'Login',     label: 'Login form' },
    { category: 'Settings',  label: 'Settings list' },
    { category: 'Checkout',  label: 'Cart summary' },
    { category: 'Collections', label: 'Grid collection' },
    { category: 'Profile',   label: 'Edit profile' },
    { category: 'Home',      label: 'Featured carousel' },
    { category: 'Login',     label: 'Social login' },
    { category: 'Wallet',    label: 'Transaction list' },
    { category: 'Welcome',   label: 'Onboarding step' },
    { category: 'Settings',  label: 'Notification prefs' },
  ];

  function renderGrid(filter) {
    const grid = document.getElementById('screenshotGrid');
    grid.innerHTML = '';
    const items = filter === 'All' ? screenshots : screenshots.filter(function (s) { return s.category === filter; });
    const displayItems = items.length > 0 ? items : screenshots.slice(0, 6);
    displayItems.forEach(function (item) {
      const card = document.createElement('div');
      card.className = 'screenshot-card';
      card.setAttribute('role', 'img');
      card.setAttribute('aria-label', item.label + ' — ' + item.category);
      card.innerHTML = `<div class="screenshot-card-inner">
        <div class="sc-top"><div class="sc-avatar"></div><div class="sc-line"></div></div>
        <div class="sc-image"></div>
        <div class="sc-title"></div>
        <div class="sc-subtitle"></div>
        <div class="sc-button"></div>
      </div>`;
      grid.appendChild(card);
    });
  }

  renderGrid('All');

  const pills = document.querySelectorAll('.filter-pill');
  pills.forEach(function (pill) {
    pill.addEventListener('click', function () {
      pills.forEach(function (p) { p.classList.remove('active'); });
      pill.classList.add('active');
      renderGrid(pill.dataset.filter);
    });
  });

  /* ── Text search preview ── */
  const textSearchBtn = document.querySelector('.text-search-btn');
  const textSearchInput = document.querySelector('.text-search-input');
  function renderTextResults() {
    const grid = document.getElementById('textResults');
    grid.innerHTML = '';
    for (let i = 0; i < 8; i++) {
      const card = document.createElement('div');
      card.className = 'text-result-card';
      card.innerHTML = '<div class="text-highlight"></div>';
      grid.appendChild(card);
    }
  }
  renderTextResults();
  textSearchBtn.addEventListener('click', renderTextResults);
  textSearchInput.addEventListener('keydown', function (e) {
    if (e.key === 'Enter') renderTextResults();
  });

  /* ── Flows toggle ── */
  const flowsBtns = document.querySelectorAll('.flows-toggle-btn');
  flowsBtns.forEach(function (btn) {
    btn.addEventListener('click', function () {
      flowsBtns.forEach(function (b) {
        b.classList.remove('active');
        b.setAttribute('aria-pressed', 'false');
      });
      btn.classList.add('active');
      btn.setAttribute('aria-pressed', 'true');

      const view = btn.dataset.view;
      document.querySelectorAll('.flows-panel').forEach(function (p) {
        p.classList.remove('active');
      });
      const panel = document.getElementById('view-' + view);
      if (panel) panel.classList.add('active');
    });
  });

  /* ── Respect prefers-reduced-motion ── */
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
    document.querySelectorAll('.marquee-row, .icon-marquee-row').forEach(function (el) {
      el.style.animation = 'none';
    });
  }

})();
</script>

</body>
</html>
